/* ------------------------------------------------------------------ */
/*  Mini-Game Builder Helper for Medical Coding                        */
/* ------------------------------------------------------------------ */

function buildMedicalMiniGame(spec: MedicalDaySpec): MiniGameConfig {
  const diff = spec.day <= 15 ? 1 : spec.day <= 30 ? 2 : spec.day <= 60 ? 3 : spec.day <= 75 ? 4 : 5;

  if (spec.gameKind === "match") {
    return matchGame(
      spec.gameType,
      spec.gameTitle,
      `Match each clinical coding concept to its correct architectural role for: ${spec.title}.`,
      diff,
      [
        { left: spec.pipelineNodes[0]?.[1] ?? "Concept A", right: spec.pipelineNodes[0]?.[2] ?? "Role A" },
        { left: spec.pipelineNodes[1]?.[1] ?? "Concept B", right: spec.pipelineNodes[1]?.[2] ?? "Role B" },
        { left: spec.pipelineNodes[2]?.[1] ?? "Concept C", right: spec.pipelineNodes[2]?.[2] ?? "Role C" },
        { left: spec.pipelineNodes[3]?.[1] ?? "Concept D", right: spec.pipelineNodes[3]?.[2] ?? "Role D" },
      ],
    );
  }

  if (spec.gameKind === "predict") {
    return predictGame(
      spec.gameType,
      spec.gameTitle,
      `// Clinical Coding Verification - Day ${spec.day}\n// Topic: ${spec.title}\nString auditVerdict = "${spec.pipelineNodes[0]?.[1]} -> ${spec.pipelineNodes[3]?.[1]}";\nSystem.out.println(auditVerdict);`,
      [
        spec.mcqCorrect,
        spec.mcqWrong[0] ?? "Option A",
        spec.mcqWrong[1] ?? "Option B",
        spec.mcqWrong[2] ?? "Option C",
      ],
      0,
      spec.mcqExpl,
      diff,
    );
  }

  if (spec.gameKind === "arrange") {
    return arrangeGame(
      spec.gameType,
      spec.gameTitle,
      `Arrange the clinical coding & billing stages in correct execution sequence for: ${spec.title}.`,
      spec.pipelineNodes.map((n, idx) => ({
        id: `med-block-${idx + 1}`,
        code: `${idx + 1}. ${n[1]} (${n[2]})`,
        order: idx + 1,
      })),
      diff,
    );
  }

  if (spec.gameKind === "error") {
    return errorGame(
      spec.gameType,
      spec.gameTitle,
      `// Clinical Documentation & Coding Audit - Day ${spec.day}\n// ${spec.title}\nclass ClaimAuditor {\n    void audit(Claim claim) {\n        // Defect condition on Day ${spec.day}\n        throw new ComplianceException("Regulatory coding violation detected");\n    }\n}`,
      [
        { line: 5, description: "Unbundled NCCI code pair or unsupported modifier detected on claim" },
        { line: 3, description: "Missing medical necessity documentation or conflicting Excludes1 diagnosis" },
      ],
      diff,
    );
  }

  if (spec.gameKind === "pipeline") {
    return pipelineGame(
      spec.gameType,
      spec.gameTitle,
      `Assemble the clinical coding architecture pipeline stages in correct execution sequence for ${spec.title}.`,
      spec.pipelineNodes.map((n) => n[1]),
      [0, 1, 2, 3],
      diff,
    );
  }

  return fillBlanksGame(
    spec.gameType,
    spec.gameTitle,
    `In clinical coding, ${spec.pipelineNodes[0]?.[1] ?? "documentation"} maps via ${spec.pipelineNodes[1]?.[1] ?? "guidelines"} to produce ${spec.pipelineNodes[3]?.[1] ?? "code"}.`,
    [
      {
        placeholder: spec.pipelineNodes[0]?.[1] ?? "documentation",
        answer: spec.pipelineNodes[0]?.[1] ?? "documentation",
        options: [spec.pipelineNodes[0]?.[1] ?? "documentation", "RandomGuess", "StaticCharge"],
      },
    ],
    diff,
  );
}

/* ------------------------------------------------------------------ */
/*  Assemble All 90 Medical Coding Lessons                             */
/* ------------------------------------------------------------------ */

export function buildMedicalCurriculum(): CourseCurriculum {
  const curriculum: CourseCurriculum = {};

  for (const spec of MEDICAL_DAYS) {
    const isProjectDay = spec.day >= 76;
    const projectConfig = isProjectDay
      ? {
          projectTitle: "Multi-Specialty Inpatient & Outpatient Clinical Coding & Auditing Engine",
          overview: "Architect and execute an end-to-end clinical chart coding, auditing, and revenue cycle remediation system. Analyze complex multi-specialty operative notes, inpatient MS-DRGs, outpatient APCs, NCCI unbundling edits, CMS-HCC risk adjustment, and statistical overpayment audits.",
          techStack: ["ICD-10-CM", "ICD-10-PCS", "CPT 2024", "HCPCS Level II", "NCCI Edits", "MS-DRGs", "Python", "Streamlit", "Docker"],
          milestone: {
            day: spec.day,
            title: spec.title,
            deliverable: `Production Deliverable for Day ${spec.day}: ${spec.description}`,
            acceptanceCriteria: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
          },
          evaluationRubric: [
            { criteria: "Coding Precision & Guideline Adherence", weight: 30 },
            { criteria: "NCCI & Modifier Compliance", weight: 30 },
            { criteria: "Denial Remediation & Appeal Rigor", weight: 20 },
            { criteria: "Risk Adjustment & Audit Defense", weight: 20 },
          ],
        }
      : undefined;

    curriculum[spec.day] = buildLesson("medical", {
      day: spec.day,
      title: spec.title,
      description: spec.description,
      learningObjectives: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
      animationPipeline: pipeline("medical", ...spec.pipelineNodes),
      miniGame: buildMedicalMiniGame(spec),
      knowledgeCheck: mcq(
        spec.mcqQuestion,
        spec.mcqCorrect,
        spec.mcqExpl,
        spec.mcqWrong[0] ?? "Option A",
        "Incorrect option.",
        spec.mcqWrong[1] ?? "Option B",
        "Incorrect option.",
        spec.mcqWrong[2] ?? "Option C",
        "Incorrect option.",
      ),
      realWorldExample: realWorld(spec.realScenario, spec.realApp, "Healthcare Clinical Coding & Revenue Cycle Management"),
      projectConfig,
    });
  }

  return curriculum;
}

export const MEDICAL_CURRICULUM = buildMedicalCurriculum();
